		HookNameSessionStart:        false,
		HookNameAgentStop:           false,
		HookNameSessionEnd:          false,
		HookNameSubagentStop:        false,
		HookNamePreToolUse:          false,
		HookNamePostToolUse:         false,
		HookNameErrorOccurred:       false,
	}

	for _, name := range names {
