func readHooksFile(t *testing.T, tempDir string) CopilotHooksFile {
	t.Helper()
	hooksPath := filepath.Join(tempDir, ".github", "hooks", HooksFileName)
	data, err := os.ReadFile(hooksPath)
	if err != nil {
		t.Fatalf("failed to read %s: %v", HooksFileName, err)
	}

