	ag := &CopilotCLIAgent{}
	input := `{"timestamp":1771480081383,"cwd":"/path/to/repo","sessionId":"` + testSessionID + `","source":"new","initialPrompt":"hi"}`

	event, err := ag.ParseHookEvent(context.Background(), HookNameSessionStart, strings.NewReader(input))

	if err != nil {
