// Package copilotcli implements the Agent interface for GitHub Copilot CLI.
package copilotcli

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

//nolint:gochecknoinits // Agent self-registration is the intended pattern
func init() {
	agent.Register(agent.AgentNameCopilotCLI, NewCopilotCLIAgent)
}

// CopilotCLIAgent implements the Agent interface for GitHub Copilot CLI.
//
//nolint:revive // CopilotCLIAgent is clearer than Agent in this context
type CopilotCLIAgent struct{}

// NewCopilotCLIAgent creates a new Copilot CLI agent instance.
func NewCopilotCLIAgent() agent.Agent {
	return &CopilotCLIAgent{}
}

// Name returns the agent registry key.
func (c *CopilotCLIAgent) Name() types.AgentName {
	return agent.AgentNameCopilotCLI
}

// Type returns the agent type identifier.
func (c *CopilotCLIAgent) Type() types.AgentType {
	return agent.AgentTypeCopilotCLI
}

// Description returns a human-readable description.
func (c *CopilotCLIAgent) Description() string {
	return "Copilot CLI - GitHub's AI-powered coding agent"
}

// IsPreview returns true because this is a new integration.
func (c *CopilotCLIAgent) IsPreview() bool { return true }

// DetectPresence checks if Copilot CLI hooks are configured in the repository.
func (c *CopilotCLIAgent) DetectPresence(ctx context.Context) (bool, error) {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		worktreeRoot = "."
	}

	hooksDir := filepath.Join(worktreeRoot, ".github", "hooks")
	if _, err := os.Stat(hooksDir); err == nil {
		return true, nil
	}
	return false, nil
}

// GetSessionID extracts the session ID from hook input.
func (c *CopilotCLIAgent) GetSessionID(input *agent.HookInput) string {
	return input.SessionID
}

// GetSessionDir returns the directory where Copilot CLI stores session transcripts.
func (c *CopilotCLIAgent) GetSessionDir(_ string) (string, error) {
	if override := os.Getenv("ENTIRE_TEST_COPILOT_SESSION_DIR"); override != "" {
		return override, nil
	}

	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("failed to get home directory: %w", err)
	}

	return filepath.Join(homeDir, ".copilot", "session-state"), nil
}

// ResolveSessionFile returns the path to a Copilot CLI session transcript file.
// Copilot CLI stores transcripts at <sessionDir>/<sessionId>/events.jsonl.
func (c *CopilotCLIAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
	return filepath.Join(sessionDir, agentSessionID, "events.jsonl")
}

// ProtectedDirs returns directories that Copilot CLI uses for config/state.
func (c *CopilotCLIAgent) ProtectedDirs() []string { return []string{".github"} }

// ReadSession reads a session from Copilot CLI's storage (JSONL transcript file).
func (c *CopilotCLIAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
	if input.SessionRef == "" {
		return nil, errors.New("session reference (transcript path) is required")
	}

	data, err := os.ReadFile(input.SessionRef)
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}

	return &agent.AgentSession{
		SessionID:  input.SessionID,
		AgentName:  c.Name(),
		SessionRef: input.SessionRef,
		StartTime:  time.Now(),
		NativeData: data,
	}, nil
}

// WriteSession writes a session to Copilot CLI's storage (JSONL transcript file).
func (c *CopilotCLIAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
	if session == nil {
		return errors.New("session is nil")
	}

	if session.AgentName != "" && session.AgentName != c.Name() {
		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
	}

	if session.SessionRef == "" {
		return errors.New("session reference (transcript path) is required")
	}

	if len(session.NativeData) == 0 {
		return errors.New("session has no native data to write")
	}

	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
		return fmt.Errorf("failed to write transcript: %w", err)
	}

	return nil
}

// FormatResumeCommand returns a command to resume a Copilot CLI session.
func (c *CopilotCLIAgent) FormatResumeCommand(sessionID string) string {
	return "copilot --resume " + sessionID
}

// ReadTranscript reads the raw JSONL transcript bytes for a session.
func (c *CopilotCLIAgent) ReadTranscript(sessionRef string) ([]byte, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}
	return data, nil
}

// ChunkTranscript splits a JSONL transcript at line boundaries.
func (c *CopilotCLIAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
	chunks, err := agent.ChunkJSONL(content, maxSize)
	if err != nil {
		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
	}
	return chunks, nil
}

// ReassembleTranscript concatenates JSONL chunks with newlines.
func (c *CopilotCLIAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	return agent.ReassembleJSONL(chunks), nil
}

package copilotcli

import (
	"context"
	"io"
	"os"
	"path/filepath"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// Ensure CopilotCLIAgent implements HookSupport at compile time.
var _ agent.HookSupport = (*CopilotCLIAgent)(nil)

// Copilot CLI hook names - these become subcommands under `entire hooks copilot-cli`
const (
	HookNameUserPromptSubmitted = "user-prompt-submitted"
	HookNameSessionStart        = "session-start"
	HookNameAgentStop           = "agent-stop"
	HookNameSessionEnd          = "session-end"
	HookNameSubagentStop        = "subagent-stop"
	HookNamePreToolUse          = "pre-tool-use"
	HookNamePostToolUse         = "post-tool-use"
	HookNameErrorOccurred       = "error-occurred"
)

// HookNames returns all hook verbs Copilot CLI supports.
// These become subcommands: entire hooks copilot-cli <verb>
func (c *CopilotCLIAgent) HookNames() []string {
	return []string{
		HookNameUserPromptSubmitted,
		HookNameSessionStart,
		HookNameAgentStop,
		HookNameSessionEnd,
		HookNameSubagentStop,
		HookNamePreToolUse,
		HookNamePostToolUse,
		HookNameErrorOccurred,
	}
}

// ParseHookEvent translates a Copilot CLI hook into a normalized lifecycle Event.
// Returns nil if the hook has no lifecycle significance (pass-through hooks).
func (c *CopilotCLIAgent) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
	switch hookName {
	case HookNameUserPromptSubmitted:
		return c.parseUserPromptSubmitted(ctx, stdin)
	case HookNameSessionStart:
		return c.parseSessionStart(stdin)
	case HookNameAgentStop:
		return c.parseAgentStop(stdin)
	case HookNameSessionEnd:
		return c.parseSessionEnd(stdin)
	case HookNameSubagentStop:
		return c.parseSubagentStop(stdin)
	case HookNamePreToolUse, HookNamePostToolUse, HookNameErrorOccurred:
		return nil, nil //nolint:nilnil // Pass-through hooks have no lifecycle action
	default:
		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
	}
}

// --- Internal hook parsing functions ---

func (c *CopilotCLIAgent) parseUserPromptSubmitted(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[userPromptSubmittedRaw](stdin)
	if err != nil {
		return nil, err
	}

	transcriptRef := c.resolveTranscriptRef(ctx, raw.SessionID)

	return &agent.Event{
		Type:       agent.TurnStart,
		SessionID:  raw.SessionID,
		SessionRef: transcriptRef,
		Prompt:     raw.Prompt,
		Timestamp:  time.Now(),
	}, nil
}

func (c *CopilotCLIAgent) parseSessionStart(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[sessionStartRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:      agent.SessionStart,
		SessionID: raw.SessionID,
		Timestamp: time.Now(),
	}, nil
}

func (c *CopilotCLIAgent) parseAgentStop(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[agentStopRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.TurnEnd,
		SessionID:  raw.SessionID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  time.Now(),
	}, nil
}

func (c *CopilotCLIAgent) parseSessionEnd(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[sessionEndRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:      agent.SessionEnd,
		SessionID: raw.SessionID,
		Timestamp: time.Now(),
	}, nil
}

func (c *CopilotCLIAgent) parseSubagentStop(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[subagentStopRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:      agent.SubagentEnd,
		SessionID: raw.SessionID,
		Timestamp: time.Now(),
	}, nil
}

// resolveTranscriptRef computes the transcript path from the session ID.
// Copilot CLI stores transcripts at ~/.copilot/session-state/<sessionId>/events.jsonl.
// The userPromptSubmitted hook does not include a transcriptPath field, so we compute it.
func (c *CopilotCLIAgent) resolveTranscriptRef(ctx context.Context, sessionID string) string {
	if override := os.Getenv("ENTIRE_TEST_COPILOT_SESSION_DIR"); override != "" {
		return filepath.Join(override, sessionID, "events.jsonl")
	}

	homeDir, err := os.UserHomeDir()
	if err != nil {
		logging.Warn(ctx, "copilot-cli: failed to get home directory for transcript resolution", "err", err)
		return ""
	}

	return filepath.Join(homeDir, ".copilot", "session-state", sessionID, "events.jsonl")
}

package copilotcli

// CopilotHooksFile represents the .github/hooks/entire.json structure.
// Copilot CLI uses a flat JSON file with version and hooks sections.
// All JSON files in .github/hooks/ are auto-discovered by the Copilot CLI.
//

type CopilotHooksFile struct {
	Version int          `json:"version"`
	Hooks   CopilotHooks `json:"hooks"`
}

// CopilotHooks contains all hook configurations using camelCase keys.
//

type CopilotHooks struct {
	UserPromptSubmitted []CopilotHookEntry `json:"userPromptSubmitted,omitempty"`
	SessionStart        []CopilotHookEntry `json:"sessionStart,omitempty"`
	AgentStop           []CopilotHookEntry `json:"agentStop,omitempty"`
	SessionEnd          []CopilotHookEntry `json:"sessionEnd,omitempty"`
	SubagentStop        []CopilotHookEntry `json:"subagentStop,omitempty"`
	PreToolUse          []CopilotHookEntry `json:"preToolUse,omitempty"`
	PostToolUse         []CopilotHookEntry `json:"postToolUse,omitempty"`
	ErrorOccurred       []CopilotHookEntry `json:"errorOccurred,omitempty"`
}

// CopilotHookEntry represents a single hook command.
// Copilot CLI hooks have a type field ("command") and a bash field for the command string.
// Optional fields: cwd, timeoutSec, env, comment.
//

type CopilotHookEntry struct {
	Type    string `json:"type"`
	Bash    string `json:"bash"`
	Comment string `json:"comment,omitempty"`
}

// userPromptSubmittedRaw is the JSON structure from userPromptSubmitted hooks.
type userPromptSubmittedRaw struct {
	Timestamp int64  `json:"timestamp"`
	Cwd       string `json:"cwd"`
	SessionID string `json:"sessionId"`
	Prompt    string `json:"prompt"`
}

// sessionStartRaw is the JSON structure from sessionStart hooks.
type sessionStartRaw struct {
	Timestamp     int64  `json:"timestamp"`
	Cwd           string `json:"cwd"`
	SessionID     string `json:"sessionId"`
	Source        string `json:"source"`
	InitialPrompt string `json:"initialPrompt"`
}

// agentStopRaw is the JSON structure from agentStop hooks.
type agentStopRaw struct {
	Timestamp      int64  `json:"timestamp"`
	Cwd            string `json:"cwd"`
	SessionID      string `json:"sessionId"`
	TranscriptPath string `json:"transcriptPath"`
	StopReason     string `json:"stopReason"`
}

// sessionEndRaw is the JSON structure from sessionEnd hooks.
type sessionEndRaw struct {
	Timestamp int64  `json:"timestamp"`
	Cwd       string `json:"cwd"`
	SessionID string `json:"sessionId"`
	Reason    string `json:"reason"`
}

// subagentStopRaw is the JSON structure from subagentStop hooks.
type subagentStopRaw struct {
	Timestamp int64  `json:"timestamp"`
	Cwd       string `json:"cwd"`
	SessionID string `json:"sessionId"`
}

package agent

import (
	"context"
	"fmt"
	"slices"
	"sync"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

var (
	registryMu sync.RWMutex
	registry   = make(map[types.AgentName]Factory)
)

// Factory creates a new agent instance
type Factory func() Agent

// Register adds an agent factory to the registry.
// Called from init() in each agent implementation.
func Register(name types.AgentName, factory Factory) {
	registryMu.Lock()
	defer registryMu.Unlock()
	registry[name] = factory
}

// Get retrieves an agent by name.
//

func Get(name types.AgentName) (Agent, error) {
	registryMu.RLock()
	defer registryMu.RUnlock()

	factory, ok := registry[name]
	if !ok {
		return nil, fmt.Errorf("unknown agent: %s (available: %v)", name, List())
	}
	return factory(), nil
}

// List returns all registered agent names in sorted order.
func List() []types.AgentName {
	registryMu.RLock()
	defer registryMu.RUnlock()

	names := make([]types.AgentName, 0, len(registry))
	for name := range registry {
		names = append(names, name)
	}
	slices.Sort(names)
	return names
}

func StringList() []string {
	registryMu.RLock()
	defer registryMu.RUnlock()

	names := make([]string, 0, len(registry))
	for name := range registry {
		names = append(names, string(name))
	}
	slices.Sort(names)
	return names
}

// DetectAll returns all agents whose DetectPresence reports true.
// Agents are checked in sorted name order (via List()) for deterministic results.
// Returns an empty slice when no agent is detected.
func DetectAll(ctx context.Context) []Agent {
	names := List() // sorted, lock-safe

	var detected []Agent
	for _, name := range names {
		ag, err := Get(name)
		if err != nil {
			continue
		}
		if present, err := ag.DetectPresence(ctx); err == nil && present {
			detected = append(detected, ag)
		}
	}
	return detected
}

// Detect attempts to auto-detect which agent is being used.
// Iterates registered agents in sorted name order for deterministic results.
// Returns the first agent whose DetectPresence reports true.
func Detect(ctx context.Context) (Agent, error) {
	detected := DetectAll(ctx)
	if len(detected) == 0 {
		return nil, fmt.Errorf("no agent detected (available: %v)", List())
	}
	return detected[0], nil
}

// Agent name constants (registry keys)
const (
	AgentNameClaudeCode types.AgentName = "claude-code"
	AgentNameCopilotCLI types.AgentName = "copilot-cli"
	AgentNameCursor     types.AgentName = "cursor"
	AgentNameGemini     types.AgentName = "gemini"
	AgentNameOpenCode   types.AgentName = "opencode"
)

// Agent type constants (type identifiers stored in metadata/trailers)
const (
	AgentTypeClaudeCode types.AgentType = "Claude Code"
	AgentTypeCopilotCLI types.AgentType = "Copilot CLI"
	AgentTypeCursor     types.AgentType = "Cursor"
	AgentTypeGemini     types.AgentType = "Gemini CLI"
	AgentTypeOpenCode   types.AgentType = "OpenCode"
	AgentTypeUnknown    types.AgentType = "Agent" // Fallback for backwards compatibility
)

// DefaultAgentName is the registry key for the default agent.
const DefaultAgentName types.AgentName = AgentNameClaudeCode

// GetByAgentType retrieves an agent by its type identifier.
//
// Note: This uses a linear search that instantiates agents until a match is found.
// This is acceptable because:
//   - Agent count is small (~2-20 agents)
//   - Agent factories are lightweight (empty struct allocation)
//   - Called infrequently (commit hooks, rewind, debug commands - not hot paths)
//   - Cost is ~400ns worst case vs milliseconds for I/O operations
//
// Only optimize if agent count exceeds 100 or profiling shows this as a bottleneck.
func GetByAgentType(agentType types.AgentType) (Agent, error) {
	registryMu.RLock()
	defer registryMu.RUnlock()

	for _, factory := range registry {
		ag := factory()
		if ag.Type() == agentType {
			return ag, nil
		}
	}

	return nil, fmt.Errorf("unknown agent type: %s", agentType)
}

// AllProtectedDirs returns the union of ProtectedDirs from all registered agents.
func AllProtectedDirs() []string {
	// Copy factories under the lock, then release before calling external code.
	registryMu.RLock()
	factories := make([]Factory, 0, len(registry))
	for _, f := range registry {
		factories = append(factories, f)
	}
	registryMu.RUnlock()

	seen := make(map[string]struct{})
	var dirs []string
	for _, factory := range factories {
		for _, d := range factory().ProtectedDirs() {
			if _, ok := seen[d]; !ok {
				seen[d] = struct{}{}
				dirs = append(dirs, d)
			}
		}
	}
	slices.Sort(dirs)
	return dirs
}

// Default returns the default agent.
// Returns nil if the default agent is not registered.
//
//nolint:errcheck // Factory pattern returns interface; error is acceptable to ignore for default
func Default() Agent {
	a, _ := Get(DefaultAgentName)
	return a
}

package cli

import (
	"github.com/entireio/cli/cmd/entire/cli/agent"
	// Import agents to ensure they are registered before we iterate
	_ "github.com/entireio/cli/cmd/entire/cli/agent/claudecode"
	_ "github.com/entireio/cli/cmd/entire/cli/agent/copilotcli"
	_ "github.com/entireio/cli/cmd/entire/cli/agent/cursor"
	_ "github.com/entireio/cli/cmd/entire/cli/agent/geminicli"
	_ "github.com/entireio/cli/cmd/entire/cli/agent/opencode"

	"github.com/spf13/cobra"
)

func newHooksCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:    "hooks",
		Short:  "Hook handlers",
		Long:   "Commands called by hooks. These are internal and not for direct user use.",
		Hidden: true, // Internal command, not for direct user use
	}

	// Git hooks are strategy-level (not agent-specific)
	cmd.AddCommand(newHooksGitCmd())

	// Dynamically add agent hook subcommands
	// Each agent that implements HookSupport gets its own subcommand tree
	for _, agentName := range agent.List() {
		ag, err := agent.Get(agentName)
		if err != nil {
			continue
		}
		if handler, ok := ag.(agent.HookSupport); ok {
			cmd.AddCommand(newAgentHooksCmd(agentName, handler))
		}
	}

	return cmd
}

