// resolveTranscriptRef computes the transcript path from the session ID.
// Copilot CLI stores transcripts at ~/.copilot/session-state/<sessionId>/events.jsonl.
// The userPromptSubmitted hook does not include a transcriptPath field, so we compute it.
func (c *CopilotCLIAgent) resolveTranscriptRef(ctx context.Context, sessionID string) string {
	if override := os.Getenv("ENTIRE_TEST_COPILOT_SESSION_DIR"); override != "" {
		return filepath.Join(override, sessionID, "events.jsonl")
	}

	homeDir, err := os.UserHomeDir()
	if err != nil {
		logging.Warn(ctx, "copilot-cli: failed to get home directory for transcript resolution", "err", err)
		return ""
	}

	return filepath.Join(homeDir, ".copilot", "session-state", sessionID, "events.jsonl")
}

// subagentStopRaw is the JSON structure from subagentStop hooks.
type subagentStopRaw struct {
	Timestamp int64  `json:"timestamp"`
	Cwd       string `json:"cwd"`
	SessionID string `json:"sessionId"`
}

func (r *HookRunner) runHookWithInput(flag string, input interface{}) error {
	r.T.Helper()

	inputJSON, err := json.Marshal(input)
	if err != nil {
		return fmt.Errorf("failed to marshal hook input: %w", err)
	}

	return r.runHookInRepoDir(flag, inputJSON)
}

func (r *HookRunner) runHookInRepoDir(hookName string, inputJSON []byte) error {
	// Run using the shared test binary
	// Command structure: entire hooks claude-code <hook-name>
	cmd := exec.Command(getTestBinary(), "hooks", "claude-code", hookName)
	cmd.Dir = r.RepoDir
	cmd.Stdin = bytes.NewReader(inputJSON)
	cmd.Env = append(gitIsolatedEnv(),
		"ENTIRE_TEST_CLAUDE_PROJECT_DIR="+r.ClaudeProjectDir,
	)

	output, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("hook %s failed: %w\nInput: %s\nOutput: %s",
			hookName, err, inputJSON, output)
	}

	r.T.Logf("Hook %s output: %s", hookName, output)
	return nil
}

// Session represents a simulated Claude Code session.
type Session struct {
	ID                string // Raw model session ID (e.g., "test-session-1")
	TranscriptPath    string
	TranscriptBuilder *TranscriptBuilder
	env               *TestEnv
}

// FileChange represents a file modification in a session.
type FileChange struct {
	Path    string
	Content string
}

