// --- handleLifecycleSubagentEnd tests ---

// TestHandleLifecycleSubagentEnd_FallsBackToPrePromptState verifies that when
// no pre-task state exists (agent doesn't have a SubagentStart hook), the handler
// falls back to the session's pre-prompt state to filter untracked files.
// Without this fallback, pre-existing untracked files (e.g., .github/hooks/entire.json)
// would be counted as "new" and create spurious task checkpoints.
func TestHandleLifecycleSubagentEnd_FallsBackToPrePromptState(t *testing.T) {
	// Cannot use t.Parallel() because we use t.Chdir()
	tmpDir := t.TempDir()
	t.Chdir(tmpDir)

	// Set up a real git repo with an initial commit
	setupGitRepoWithCommit(t, tmpDir)
	paths.ClearWorktreeRootCache()

	// Create .entire/tmp for state files
	entireTmpDir := filepath.Join(tmpDir, ".entire", "tmp")
	if err := os.MkdirAll(entireTmpDir, 0o750); err != nil {
		t.Fatalf("Failed to create .entire/tmp: %v", err)
	}

	// Create a pre-existing untracked file (simulates .github/hooks/entire.json)
	hookDir := filepath.Join(tmpDir, ".github", "hooks")
	if err := os.MkdirAll(hookDir, 0o750); err != nil {
		t.Fatalf("Failed to create .github/hooks: %v", err)
	}
	if err := os.WriteFile(filepath.Join(hookDir, "entire.json"), []byte(`{"version":1}`), 0o644); err != nil {
		t.Fatalf("Failed to create entire.json: %v", err)
	}

	sessionID := "test-subagent-fallback-session"

	// Write pre-prompt state listing the untracked file
	prePromptState := PrePromptState{
		SessionID:      sessionID,
		Timestamp:      time.Now().UTC().Format(time.RFC3339),
		UntrackedFiles: []string{".github/hooks/entire.json"},
	}
	prePromptData, err := json.Marshal(prePromptState)
	if err != nil {
		t.Fatalf("Failed to marshal pre-prompt state: %v", err)
	}
	prePromptFile := filepath.Join(entireTmpDir, "pre-prompt-"+sessionID+".json")
	if err := os.WriteFile(prePromptFile, prePromptData, 0o600); err != nil {
		t.Fatalf("Failed to write pre-prompt state: %v", err)
	}

	// Do NOT create a pre-task state file — simulates an agent without SubagentStart hook

	ag := newMockAgent()
	event := &agent.Event{
		Type:      agent.SubagentEnd,
		SessionID: sessionID,
		ToolUseID: "tool-use-123",
		Timestamp: time.Now(),
	}

	// handleLifecycleSubagentEnd should succeed: the pre-prompt fallback filters out
	// the pre-existing untracked file, resulting in no file changes → skip task checkpoint
	err = handleLifecycleSubagentEnd(context.Background(), ag, event)
	if err != nil {
		t.Errorf("expected no error with pre-prompt state fallback, got: %v", err)
	}
}

// TestHandleLifecycleSubagentEnd_NoPrePromptState_NoPreTaskState verifies that when
// neither pre-task nor pre-prompt state exists, pre-existing untracked files are treated
// as new (the nil-untracked path through DetectFileChanges). This is the existing behavior
// before the fallback was added — it creates a task checkpoint because untracked files
// look "new".
func TestHandleLifecycleSubagentEnd_NoPrePromptState_NoPreTaskState(t *testing.T) {
	// Cannot use t.Parallel() because we use t.Chdir()
	tmpDir := t.TempDir()
	t.Chdir(tmpDir)

	// Set up a real git repo with an initial commit
	setupGitRepoWithCommit(t, tmpDir)
	paths.ClearWorktreeRootCache()

	// Create .entire/tmp for state files
	entireTmpDir := filepath.Join(tmpDir, ".entire", "tmp")
	if err := os.MkdirAll(entireTmpDir, 0o750); err != nil {
		t.Fatalf("Failed to create .entire/tmp: %v", err)
	}

	// Create a pre-existing untracked file
	hookDir := filepath.Join(tmpDir, ".github", "hooks")
	if err := os.MkdirAll(hookDir, 0o750); err != nil {
		t.Fatalf("Failed to create .github/hooks: %v", err)
	}
	if err := os.WriteFile(filepath.Join(hookDir, "entire.json"), []byte(`{"version":1}`), 0o644); err != nil {
		t.Fatalf("Failed to create entire.json: %v", err)
	}

	sessionID := "test-no-state-session"

	// No pre-prompt state, no pre-task state — the handler will see nil untracked
	// and DetectFileChanges will treat all untracked files as "new"

	ag := newMockAgent()
	event := &agent.Event{
		Type:      agent.SubagentEnd,
		SessionID: sessionID,
		ToolUseID: "tool-use-456",
		Timestamp: time.Now(),
	}

	// This will attempt to create a task checkpoint because .github/hooks/entire.json
	// looks like a new file. It may fail at SaveTaskStep due to missing session state,
	// but the important thing is it doesn't return nil (it tries to create a checkpoint).
	err := handleLifecycleSubagentEnd(context.Background(), ag, event)
	// We expect either an error (missing session state for SaveTaskStep) or success
	// (if it manages to save). The key assertion is this path does NOT silently skip —
	// unlike the fallback path which correctly skips.
	// Since we can't easily distinguish "skipped due to no changes" from "failed at
	// SaveTaskStep", we verify indirectly: the first test passes (fallback works),
	// and this test shows the contrasting behavior without fallback.
	_ = err // Result depends on session state setup; the contrast with the above test is what matters
}

// --- Helper functions for test setup ---

